/**
 * kdramascraperapi – Express Scraper API
 * Generated by @zjkm666/scraperapi
 * Source: https://kisskh.do/
 *
 * Run:
 *   npm install
 *   npm run dev   # http://localhost:3000
 *
 * Customize:
 *   Edit api.config.js to add GET/POST endpoints.
 */
require('dotenv').config();
const express = require('express');
const cors = require('cors');
const NodeCache = require('node-cache');
const config = require('./api.config');
const { scrape } = require('./scraper');
const axios = require('axios');

const apiHttp = axios.create({
  timeout: 15000,
  maxRedirects: 5,
  headers: {
    'User-Agent':
      'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36',
    Accept: 'application/json, text/plain, */*',
  },
  validateStatus: () => true,
});

async function fetchJson(url, fetchOpts = {}) {
  const headers = { ...(fetchOpts.headers || {}) };
  const res = await apiHttp.get(url, {
    headers,
    timeout: fetchOpts.timeout || 15000,
    params: fetchOpts.params,
  });
  if (res.status >= 400) {
    const err = new Error(`HTTP ${res.status} for ${url}`);
    err.status = res.status;
    throw err;
  }
  return res.data;
}

const app = express();
const PORT = process.env.PORT || 3000;
// SOURCE_URL env override (documented in .env.example) takes precedence over config
const SOURCE_BASE = (process.env.SOURCE_URL || config.sourceUrl || '').replace(/\/$/, '');

// ── Middleware ───────────────────────────────────────────────────────
app.disable('x-powered-by');
const corsOrigin = process.env.CORS_ORIGIN;
app.use(
  cors(
    corsOrigin
      ? { origin: corsOrigin.split(',').map((s) => s.trim()).filter(Boolean) }
      : undefined
  )
);
app.use(express.json({ limit: '1mb' }));
app.use(express.urlencoded({ extended: true, limit: '1mb' }));

// minimal security headers (helmet-lite, no extra dep)
app.use((_req, res, next) => {
  res.set('X-Content-Type-Options', 'nosniff');
  res.set('X-Frame-Options', 'DENY');
  res.set('Referrer-Policy', 'no-referrer');
  res.set('Permissions-Policy', 'camera=(), microphone=(), geolocation=()');
  next();
});

// simple in-memory rate limiter: 120 req / 60s per IP (no extra dep)
const RATE_WINDOW_MS = Number(process.env.RATE_WINDOW_MS) || 60_000;
const RATE_MAX = Number(process.env.RATE_MAX) || 120;
const _hits = new Map();
setInterval(() => {
  const now = Date.now();
  for (const [ip, arr] of _hits) {
    const fresh = arr.filter((t) => now - t < RATE_WINDOW_MS);
    if (fresh.length) _hits.set(ip, fresh);
    else _hits.delete(ip);
  }
}, RATE_WINDOW_MS).unref?.();
app.use((req, res, next) => {
  const ip = req.ip || req.socket?.remoteAddress || 'unknown';
  const now = Date.now();
  const arr = (_hits.get(ip) || []).filter((t) => now - t < RATE_WINDOW_MS);
  arr.push(now);
  _hits.set(ip, arr);
  if (arr.length > RATE_MAX) {
    res.set('Retry-After', String(Math.ceil(RATE_WINDOW_MS / 1000)));
    return res.status(429).json({ success: false, error: 'Rate limit exceeded, slow down' });
  }
  next();
});

// simple logger
app.use((req, _res, next) => {
  console.log(`${new Date().toISOString()} ${req.method} ${req.path}`);
  next();
});

// ── Cache (optional) ─────────────────────────────────────────────────
const cacheEnabled = !!(config.cache && (config.cache.enabled !== false));
const cacheTtl = (config.cache && config.cache.ttl) || 300;
const cacheCheckperiod = (config.cache && config.cache.checkperiod) || 60;
const cache = cacheEnabled ? new NodeCache({ stdTTL: cacheTtl, checkperiod: cacheCheckperiod, useClones: false }) : null;

function cacheKeyFor(endpoint, url, req) {
  // include body/query for POST/GET variance
  const extra = endpoint.method?.toUpperCase() === 'POST' ? req.body : req.query;
  try {
    return `${endpoint.method}:${endpoint.path}:${url}::${JSON.stringify(extra || {})}`;
  } catch {
    return `${endpoint.method}:${endpoint.path}:${url}`;
  }
}

function isCacheEnabledFor(endpoint) {
  if (!cacheEnabled || !cache) return false;
  if (endpoint.cache === false) return false;
  if (endpoint.cache === true) return true;
  if (endpoint.cache && typeof endpoint.cache === 'object' && endpoint.cache.enabled === false) return false;
  return true;
}

function getTtlFor(endpoint) {
  if (endpoint.cache && typeof endpoint.cache === 'object' && endpoint.cache.ttl) return Number(endpoint.cache.ttl);
  return undefined;
}

// ── Helpers ──────────────────────────────────────────────────────────
function getBase() {
  return SOURCE_BASE;
}

function isAllowedTarget(targetUrl, ep) {
  try {
    const u = new URL(targetUrl);
    const baseOrigin = new URL(getBase()).origin;
    if (u.origin === baseOrigin) return true;
    // explicit per-endpoint allowlist for CDN / third-party JSON (e.g. HLS hosts)
    const allow = (ep && ep.allowHosts) || [];
    return allow.some((h) => {
      if (!h) return false;
      if (h.startsWith('*.')) return u.hostname.endsWith(h.slice(1));
      return u.hostname === h;
    });
  } catch {
    return false;
  }
}

function resolveUrl(endpoint, req) {
  const base = getBase();
  let out;
  if (typeof endpoint.buildUrl === 'function') {
    const built = endpoint.buildUrl(base, req);
    if (typeof built !== 'string' || !built.trim()) throw new Error('buildUrl must return a string URL');
    out = built.trim();
  } else if (typeof endpoint.buildUrl === 'string') {
    // string template with :param placeholders, e.g. "/product/:id"
    let url = endpoint.buildUrl;
    // replace :param from body/query/params
    const params = { ...(req.params || {}), ...(req.query || {}), ...(req.body || {}) };
    for (const [k, v] of Object.entries(params)) {
      url = url.replaceAll(`:${k}`, encodeURIComponent(String(v)));
    }
    // reject unfilled placeholders to avoid malformed / injectable URLs
    if (/\/:[a-zA-Z0-9_]+/.test(url)) throw new Error('Missing required URL parameter');
    out = url.startsWith('/') ? base + url : url;
  } else if (endpoint.url) {
    // deprecated alias for buildUrl string
    out = endpoint.url.startsWith('http') ? endpoint.url : base + endpoint.url;
  } else {
    out = base + (endpoint.pathSuffix || '');
  }
  // SSRF guard: only allow same-origin targets as sourceUrl (+ ep.allowHosts)
  if (!isAllowedTarget(out, endpoint)) throw new Error('Resolved URL is not allowed (must stay on source origin)');
  return out;
}

function mergeFetchOpts(ep) {
  const merged = { ...(config.fetchOpts || {}), ...(ep.fetchOpts || {}) };
  const headers = {
    ...((config.fetchOpts && config.fetchOpts.headers) || {}),
    ...((ep.fetchOpts && ep.fetchOpts.headers) || {}),
    ...(ep.headers || {}),
  };
  if (Object.keys(headers).length) merged.headers = headers;
  else delete merged.headers;
  return merged;
}

function validateConfig() {
  if (!getBase() || !/^https?:\/\//.test(getBase())) {
    throw new Error('sourceUrl must be a valid http(s) URL (api.config.js or SOURCE_URL env)');
  }
  if (!Array.isArray(config.endpoints) || config.endpoints.length === 0) {
    console.warn('⚠ api.config.js: no endpoints defined. Add entries to config.endpoints.');
  }
}

// Resolve UI-style "dramaId + ep number" → KissKH episode object id.
// Endpoints with resolveEpisode:true accept EITHER:
//   ?epsId=144044            (episode object id, preferred)
//   ?dramaId=8409&ep=1       (drama id + episode number, as shown in UI)
// A lone ?ep= without dramaId keeps legacy meaning (episode object id).
async function ensureEpsId(req) {
  const q = req.query || {};
  if (q.epsId) return;
  const dramaId = q.dramaId || q.id || '';
  if (!dramaId && q.ep != null && q.ep !== '') return; // legacy: lone ?ep= means episode id
  const hasDrama = dramaId !== '' && dramaId != null;
  const numRaw = q.epNum ?? q.number ?? (hasDrama ? q.ep : undefined);
  if (!hasDrama || numRaw == null || numRaw === '') {
    const e = new Error('Provide epsId (episode id), or dramaId + ep (episode number as shown in UI)');
    e.status = 400;
    throw e;
  }
  const detailUrl = `${getBase()}/api/DramaList/Drama/${encodeURIComponent(String(dramaId))}?isq=false`;
  const detail = await fetchJson(detailUrl, {
    headers: { Referer: `${getBase()}/`, Origin: getBase() },
  });
  const episodes = detail?.episodes || detail?.data?.episodes || [];
  const ep = episodes.find((e) => String(e.number ?? e.episode) === String(numRaw));
  if (!ep || ep.id == null) {
    const e = new Error(`Episode number ${numRaw} not found in drama ${dramaId} (see GET /api/drama?id=${dramaId})`);
    e.status = 404;
    throw e;
  }
  req.query.epsId = String(ep.id);
}

// ── Auto-register endpoints from config ──────────────────────────────
function registerEndpoints() {
  for (const ep of config.endpoints) {
    const method = (ep.method || 'GET').toLowerCase();
    if (!['get', 'post'].includes(method)) {
      console.warn(`Skipping endpoint with unsupported method: ${ep.method} ${ep.path}`);
      continue;
    }

    app[method](ep.path, async (req, res) => {
      const start = Date.now();
      if (ep.resolveEpisode) {
        try {
          await ensureEpsId(req);
        } catch (e) {
          const status = e.status && e.status < 600 ? e.status : 502;
          return res.status(status).json({ success: false, error: e.message });
        }
      }
      let targetUrl;
      try {
        targetUrl = resolveUrl(ep, req);
      } catch (e) {
        return res.status(400).json({ success: false, error: e.message });
      }

      // per-endpoint renderJs override (defaults to global or false)
      const renderJs = ep.renderJs != null ? !!ep.renderJs : !!config.renderJs;
      const useCache = isCacheEnabledFor(ep);
      const cacheKey = useCache ? cacheKeyFor(ep, targetUrl, req) : null;

      if (useCache) {
        const hit = cache.get(cacheKey);
        if (hit !== undefined) {
          let data = hit;
          let extra = {};
          if (typeof ep.map === 'function') {
            const m = ep.map(hit, req);
            if (m && typeof m === 'object' && !Array.isArray(m) && 'data' in m) {
              ({ data, ...extra } = m);
            } else {
              data = m;
            }
          }
          res.set('X-Cache', 'HIT');
          return res.json({
            success: true,
            cached: true,
            source: targetUrl,
            count: Array.isArray(data) ? data.length : data ? 1 : 0,
            data,
            ...extra,
            tookMs: Date.now() - start,
          });
        }
      }

      try {
        const isApi = ep.kind === 'api' || ep.api === true;
        let raw;
        if (isApi) {
          const opts = mergeFetchOpts(ep);
          raw = await fetchJson(targetUrl, {
            ...opts,
            headers: { Referer: `${getBase()}/`, Origin: getBase(), ...(opts.headers || {}) },
          });
        } else {
          raw = await scrape({
            url: targetUrl,
            selector: ep.selector,
            fields: ep.fields || {},
            renderJs,
            fetchOpts: mergeFetchOpts(ep),
            single: !!ep.single,
            limit: ep.limit,
          });
        }
        // cache the RAW upstream payload so one fetch serves all map variants
        if (useCache) {
          const ttl = getTtlFor(ep);
          if (ttl) cache.set(cacheKey, raw, ttl);
          else cache.set(cacheKey, raw);
          res.set('X-Cache', 'MISS');
        }

        // per-endpoint transform: fn(raw, req) → array | { data, ...extra }
        let data = raw;
        let extra = {};
        if (typeof ep.map === 'function') {
          const m = ep.map(raw, req);
          if (m && typeof m === 'object' && !Array.isArray(m) && 'data' in m) {
            ({ data, ...extra } = m);
          } else {
            data = m;
          }
        }

        res.json({
          success: true,
          cached: false,
          source: targetUrl,
          count: Array.isArray(data) ? data.length : data ? 1 : 0,
          data,
          ...extra,
          tookMs: Date.now() - start,
        });
      } catch (err) {
        console.error(`[${ep.method} ${ep.path}] scrape failed:`, err.message);
        const status = err.status && err.status < 500 ? err.status : 502;
        res.status(status).json({
          success: false,
          error: 'Scrape failed',
          details: err.message,
          source: targetUrl,
        });
      }
    });

    const tag = ep.kind === 'api' || ep.api === true ? '[API]' : `selector "${ep.selector}"`;
    console.log(`  ↳ ${method.toUpperCase().padEnd(4)} ${ep.path}  →  ${tag}${ep.renderJs ? ' [JS]' : ''}`);
  }
}

// ── Health / meta ────────────────────────────────────────────────────
app.get('/', (_req, res) => {
  res.json({
    name: config.name,
    sourceUrl: getBase(),
    endpoints: config.endpoints
      .map((e) => ({
        method: e.method,
        path: e.path,
        kind: e.kind === 'api' || e.api === true ? 'api' : 'scrape',
        selector: e.selector,
        description: e.description || '',
      }))
      .concat([
        {
          method: 'GET',
          path: '/api/kkey',
          kind: 'api',
          description: 'Mint stream/sub kkeys – GET /api/kkey?dramaId=8409&epsId=144044 or ?dramaId=8409&ep=1 (needs Playwright; partial:true means sub key still missing – retry fresh=1)',
        },
        {
          method: 'GET',
          path: '/api/stream',
          kind: 'api',
          description: 'Proxy .m3u8 with CORS + Referer, rewrites segments – GET /api/stream?src=<m3u8>',
        },
        {
          method: 'GET',
          path: '/api/segment',
          kind: 'api',
          description: 'Proxy segment/key/subtitle bytes with CORS + Referer – GET /api/segment?src=<ts|key|srt>',
        },
      ]),
    cache: cacheEnabled ? { enabled: true, ttl: cacheTtl, keys: cache.keys().length } : { enabled: false },
    docs: 'Edit api.config.js to customize GET/POST endpoints. Restart server after changes.',
  });
});

app.get('/health', (_req, res) => res.json({ status: 'ok', uptime: process.uptime() }));

app.get('/cache/stats', (_req, res) => {
  if (!cache) return res.json({ enabled: false });
  res.json({ enabled: true, ...cache.getStats(), keys: cache.keys().length });
});

app.delete('/cache', (req, res) => {
  if (!cache) return res.json({ enabled: false, message: 'Cache disabled' });
  // Optional protection: set CACHE_CLEAR_TOKEN env to require token
  const required = process.env.CACHE_CLEAR_TOKEN;
  if (required) {
    const got = req.headers['x-cache-token'] || req.query.token;
    if (got !== required) return res.status(401).json({ success: false, error: 'Unauthorized' });
  }
  cache.flushAll();
  res.json({ success: true, message: 'Cache cleared' });
});

// ── kkey minter (needs Playwright + Chromium; short-TTL cache – keys live seconds)
// GET /api/kkey?dramaId=8409&epsId=144044  or  ?dramaId=8409&ep=1[&fresh=1]
// visits the episode page headlessly and sniffs the stream/sub kkeys.
// Frontend play-time flow: /api/kkey → immediately /api/episode?kkey= + /api/sub?kkey=
// Cache: KKEY_CACHE_TTL seconds (default 45). Concurrent mints for the same
// episode share one in-flight browser run. Pass fresh=1 to bypass the cache
// (e.g. upstream rejected a cached key with 403).
const KKEY_CACHE_TTL = Number(process.env.KKEY_CACHE_TTL) || 45;
const keyCache = new NodeCache({ stdTTL: KKEY_CACHE_TTL, checkperiod: 30, useClones: false });
const inflightMints = new Map();

app.get('/api/kkey', async (req, res) => {
  const start = Date.now();
  const dramaId = req.query?.dramaId || req.query?.id || '';
  const epsIdParam = req.query?.epsId || '';
  // ep number accepted when dramaId given (?dramaId=8409&ep=1); lone ?ep= keeps legacy id meaning
  const epNumParam = !epsIdParam ? (req.query?.epNum ?? req.query?.number ?? (dramaId ? req.query?.ep : undefined)) : undefined;
  if (!dramaId) return res.status(400).json({ success: false, error: 'Missing required query param: dramaId' });
  if (!epsIdParam && (epNumParam == null || epNumParam === '')) {
    return res.status(400).json({ success: false, error: 'Missing required query param: epsId (or ep episode number)' });
  }
  const ck = `kkey:${dramaId}:${epsIdParam || `n${epNumParam}`}`;
  const fresh = req.query?.fresh === '1' || req.query?.fresh === 'true';
  if (!fresh) {
    const hit = keyCache.get(ck);
    if (hit) {
      res.set('X-Cache', 'HIT');
      return res.json({ success: true, cached: true, source: hit.pageUrl, data: hit, tookMs: Date.now() - start });
    }
  }
  try {
    const { mintKkeys, episodePageUrl } = require('./scraper');
    let p = inflightMints.get(ck);
    if (!p) {
      p = (async () => {
        const detailUrl = `${getBase()}/api/DramaList/Drama/${encodeURIComponent(String(dramaId))}?isq=false`;
        const detail = await fetchJson(detailUrl, {
          headers: { Referer: `${getBase()}/`, Origin: getBase() },
        });
        const episodes = detail?.episodes || detail?.data?.episodes || [];
        const ep = epsIdParam
          ? episodes.find((e) => String(e.id) === String(epsIdParam))
          : episodes.find((e) => String(e.number ?? e.episode) === String(epNumParam));
        if (!ep || ep.id == null) {
          const what = epsIdParam ? `Episode ${epsIdParam}` : `Episode number ${epNumParam}`;
          const e = new Error(`${what} not found in drama ${dramaId} (see GET /api/drama?id=${dramaId})`);
          e.status = 404;
          throw e;
        }
        const epsId = String(ep.id);
        const pageUrl = episodePageUrl(getBase(), {
          title: detail?.title || detail?.data?.title,
          dramaId,
          epsNum: ep.number ?? ep.episode ?? 1,
          epsId,
        });
        const keys = await mintKkeys({ pageUrl, timeoutMs: Number(req.query.timeoutMs) || 30000 });
        if (!keys.streamKey && !keys.subKey) {
          const e = new Error('No kkeys observed on episode page (site may be challenging headless browsers)');
          e.status = 502;
          e.source = pageUrl;
          throw e;
        }
        return { dramaId: String(dramaId), epsId: String(epsId), epsNum: ep.number ?? null, ...keys };
      })().finally(() => inflightMints.delete(ck));
      inflightMints.set(ck, p);
    }
    const data = await p;
    // Complete mints get the full TTL; partials (stream-only) get 10s so a
    // follow-up retry can mint the missing sub key instead of re-serving it.
    const complete = !!(data.streamKey && data.subKey);
    if (!complete) data.partial = true;
    keyCache.set(ck, data, complete ? undefined : 10);
    res.set('X-Cache', 'MISS');
    res.json({
      success: true,
      cached: false,
      source: data.pageUrl,
      data,
      tookMs: Date.now() - start,
    });
  } catch (e) {
    console.error('[GET /api/kkey] failed:', e.message);
    const status = e.status && e.status < 600 ? e.status : 502;
    const out = { success: false, error: status === 503 ? e.message : status === 404 ? e.message : 'kkey mint failed', details: e.message };
    if (e.source) out.source = e.source;
    res.status(status).json(out);
  }
});

// ── Stream proxy (fixes CDN hotlink/CORS blocks) ───────────────────────
// Browsers can't set Referer, and the CDN typically 403s foreign origins
// and omits CORS headers – so hls.js fails loading segments directly.
// Proxy through here instead: playlist URIs are rewritten to /api/segment
// (or nested /api/stream for master playlists), served same-origin with
// CORS * and upstream Referer injected server-side.
//   GET /api/stream?src=<url-encoded .m3u8 from /api/episode>
//   GET /api/segment?src=<url-encoded segment/key/init URL>
const { checkMediaSrc, proxyPlaylistUrls } = require('./scraper');

function proxyBase(req) {
  return `${req.protocol}://${req.get('host')}`;
}

app.get('/api/stream', async (req, res) => {
  const src = req.query?.src || req.query?.url || '';
  const bad = checkMediaSrc(src, ['.m3u8']);
  if (bad) return res.status(400).json({ success: false, error: bad });
  try {
    const upstream = await apiHttp.get(src, {
      headers: { Referer: `${getBase()}/`, Origin: getBase() },
      responseType: 'text',
      maxContentLength: 10 * 1024 * 1024,
    });
    if (upstream.status >= 400) {
      return res.status(502).json({ success: false, error: `Upstream ${upstream.status} for playlist`, source: src });
    }
    const out = proxyPlaylistUrls(String(upstream.data), src, proxyBase(req));
    res.set('Content-Type', 'application/vnd.apple.mpegurl');
    res.set('Access-Control-Allow-Origin', '*');
    res.set('Cache-Control', 'public, max-age=30');
    res.send(out);
  } catch (e) {
    console.error('[GET /api/stream] failed:', e.message);
    res.status(502).json({ success: false, error: 'Playlist proxy failed', details: e.message, source: src });
  }
});

app.get('/api/segment', (req, res) => {
  const src = req.query?.src || req.query?.url || '';
  const bad = checkMediaSrc(src, ['.ts', '.m4s', '.mp4', '.aac', '.key', '.vtt', '.srt', '.mpd']);
  if (bad) return res.status(400).json({ success: false, error: bad });
  const headers = { Referer: `${getBase()}/`, Origin: getBase() };
  if (req.headers.range) headers.Range = req.headers.range;
  apiHttp
    .get(src, { headers, responseType: 'stream', timeout: 30000, validateStatus: () => true })
    .then((upstream) => {
      if (upstream.status >= 400) {
        return res.status(502).json({ success: false, error: `Upstream ${upstream.status} for segment`, source: src });
      }
      res.status(upstream.status);
      for (const h of ['content-type', 'content-length', 'content-range', 'accept-ranges', 'cache-control']) {
        if (upstream.headers[h]) res.set(h, upstream.headers[h]);
      }
      if (!res.get('Cache-Control')) res.set('Cache-Control', 'public, max-age=300');
      res.set('Access-Control-Allow-Origin', '*');
      upstream.data.on('error', () => res.destroy());
      upstream.data.pipe(res);
    })
    .catch((e) => {
      console.error('[GET /api/segment] failed:', e.message);
      if (!res.headersSent) res.status(502).json({ success: false, error: 'Segment proxy failed', details: e.message, source: src });
    });
});

// ── Boot ─────────────────────────────────────────────────────────────
validateConfig();
registerEndpoints();

// 404 – must be after registerEndpoints
app.use((req, res) => {
  res.status(404).json({
    success: false,
    error: 'Not found',
    available: config.endpoints
      .map((e) => `${e.method} ${e.path}`)
      .concat(['GET /api/kkey', 'GET /api/stream', 'GET /api/segment', 'GET /', 'GET /health']),
  });
});

if (require.main === module) {
  const server = app.listen(PORT, () => {
    console.log(`\n  🚀 kdramascraperapi running at http://localhost:${PORT}`);
    console.log(`     Source: ${getBase()}`);
    console.log(`     Cache : ${cacheEnabled ? `enabled (TTL ${cacheTtl}s)` : 'disabled'}`);
    console.log(`     Try   : curl http://localhost:${PORT}${config.endpoints[0]?.path || '/products'}\n`);
    // warm the headless browser in the background so the first mint is fast
    setImmediate(() => {
      try {
        const { warmBrowser } = require('./scraper');
        warmBrowser().then((ok) => ok && console.log('     Browser: warmed ✓'));
      } catch {}
    });
  });
  const shutdown = () => {
    server.close(() => {
      try {
        const { closeBrowser } = require('./scraper');
        if (typeof closeBrowser === 'function') closeBrowser().finally(() => process.exit(0));
        else process.exit(0);
      } catch {
        process.exit(0);
      }
    });
    setTimeout(() => process.exit(0), 5000).unref?.();
  };
  process.once('SIGINT', shutdown);
  process.once('SIGTERM', shutdown);
}

module.exports = app;
